set -euo pipefail
command -v node >/dev/null 2>&1 || { echo 'Node.js is required.' >&2; exit 1; }
node <<'AF_BIOLOGY_EXPANSION_NODE'
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const files={"src/lib/subjects.ts": "// The subjects listed under \"Simulations\" in the main menu.\n//\n// THIS IS THE ONE FILE TO EDIT WHEN YOU ADD A SUBJECT. To add, say, Chemistry:\n//   1. Create its hub page at the href below (copy src/app/mathematics/page.tsx\n//      to src/app/chemistry/page.tsx and change the title and simulation list).\n//   2. Add one entry to SUBJECTS below.\n// The desktop dropdown and the mobile menu both update automatically.\n//\n// status: 'live'  -> a normal link.\n//         'soon'  -> shown greyed out with a \"Coming soon\" tag and no link, so\n//                    you can announce a subject before its hub page exists.\n\nexport type SubjectStatus = 'live' | 'soon';\n\nexport interface Subject {\n  slug: string;\n  label: string;\n  /** The subject's hub page. Its simulations live underneath this path. */\n  href: string;\n  icon: string;\n  description: string;\n  status: SubjectStatus;\n}\n\nexport const SUBJECTS: Subject[] = [\n  {\n    slug: 'physics',\n    label: 'Physics',\n    href: '/simulations',\n    icon: '⚛️',\n    description: 'Mechanics, electricity, waves, optics and more',\n    status: 'live',\n  },\n  {\n    slug: 'mathematics',\n    label: 'Mathematics',\n    href: '/mathematics',\n    icon: '📐',\n    description: 'Trigonometry and the maths behind physics',\n    status: 'live',\n  },\n  { slug: 'biology', label: 'Biology', href: '/biology', icon: '🧬', description: 'Cells, division, plants, classification and classroom activities', status: 'live' },\n  // Examples — uncomment one (and create its hub page) when you're ready:\n  // { slug: 'biology',   label: 'Biology',   href: '/biology',   icon: '🧬', description: 'Cells, genetics and ecosystems',            status: 'soon' },\n  // { slug: 'it',        label: 'IT',        href: '/it',        icon: '💻', description: 'Computing, networks and algorithms',        status: 'soon' },\n  {\n    slug: 'chemistry',\n    label: 'Chemistry',\n    href: '/chemistry',\n    icon: '🧪',\n    description: 'Periodic table, compounds and perovskite materials',\n    status: 'live',\n  },\n];\n\n/** True if `pathname` is this subject's hub or any page beneath it. */\nexport function isSubjectPath(pathname: string, subject: Subject): boolean {\n  if (subject.slug === 'physics' && (pathname === '/geophysics' || pathname.startsWith('/geophysics/'))) return true;\n  return pathname === subject.href || pathname.startsWith(subject.href + '/');\n}\n", "src/lib/biology/lessons.ts": "export type LessonId='cells'|'mitosis'|'meiosis'|'transpiration'|'classification'|'life-processes';\nexport type Step={name:string;detail:string};\nexport type Question={prompt:string;choices:string[];answer:number;why:string};\nexport type Lesson={title:string;intro:string;principle:string;steps:Step[];questions:Question[];investigation:string[];teacher:string;misconception:string;source:string;limit:string};\nconst q=(prompt:string,choices:string[],answer:number,why:string):Question=>({prompt,choices,answer,why});\nexport const lessons:Record<LessonId,Lesson>={\n cells:{title:'Cells and organelles',intro:'Compare simplified plant and animal cells. Select an organelle to connect its structure with its function.',principle:'Cells are the basic units of living organisms; structures support different functions.',steps:[\n {name:'Cell membrane',detail:'A selectively permeable boundary controls exchange with the surroundings. Plant cells have a membrane inside the cell wall.'},\n {name:'Cytoplasm',detail:'The cytosol is fluid inside the cell; many metabolic reactions occur here. Cytoplasm includes the cytosol and organelles outside the nucleus.'},\n {name:'Nucleus',detail:'Contains most of the cell’s DNA. Gene expression helps regulate cell activities. Not every specialised animal cell retains a nucleus.'},\n {name:'Mitochondrion',detail:'Supports aerobic respiration and ATP production. Plant cells have mitochondria as well as chloroplasts.'},\n {name:'Ribosomes',detail:'Build proteins using instructions carried by messenger RNA. They occur free in the cytoplasm and on rough endoplasmic reticulum.'},\n {name:'Cell wall',detail:'The cellulose-rich plant cell wall supports and protects the cell. Animal cells do not have a cell wall.'},\n {name:'Chloroplast',detail:'In photosynthetic plant tissues, chloroplasts capture light energy for photosynthesis. Many root cells lack chloroplasts.'},\n {name:'Central vacuole',detail:'A large compartment in many mature plant cells stores water and solutes. Turgor pressure contributes to support.'}],\n questions:[q('Which structure makes proteins?',['Nucleus','Ribosomes','Cell wall'],1,'Ribosomes assemble proteins; the nucleus contains genetic instructions.'),q('Which comparison is correct?',['Plants have no mitochondria','All plant cells have chloroplasts','Plant and animal cells have membranes'],2,'Both have membranes. Photosynthetic plant cells also contain chloroplasts.'),q('Which helps support a typical mature plant cell?',['Cell wall and turgor','Only a nucleus','Only ribosomes'],0,'The wall resists the pressure generated by water inside the cell.')],\n investigation:['Compare both cell types and record four shared structures.','Select the membrane and explain why a wall cannot replace it.','Explain why a root cell may lack chloroplasts but still require mitochondria.'],teacher:'Ask pairs to act as an organelle and a cell: one names a task, the other selects the structure. Compare leaf and root cells before generalising about plants.',misconception:'Plant cells respire too. Not every plant cell contains chloroplasts. The illustration omits ER, Golgi and other structures.',source:'4-3-eukaryotic-cells',limit:'Selected organelles only; not a scale drawing or a complete inventory.'},\n mitosis:{title:'Mitosis and the cell cycle',intro:'Step through DNA replication, chromosome alignment, separation and the production of two daughter cells.',principle:'One DNA replication precedes one nuclear division; chromosome set number is maintained.',steps:[\n {name:'G1 · before replication',detail:'Our simplified diploid cell has 2n = 4: two homologous pairs. Each chromosome contains one DNA molecule.'},\n {name:'S/G2 · DNA copied',detail:'DNA replicates during S phase. There are still 4 chromosomes, now with 8 sister chromatids; counting is by centromeres, not DNA strands.'},\n {name:'Prophase / prometaphase',detail:'Chromosomes condense, the spindle forms and the nuclear envelope breaks down. Each sister chromatid attaches toward an opposite pole.'},\n {name:'Metaphase',detail:'Replicated chromosomes align individually at the equator. Homologous chromosomes do not pair as tetrads.'},\n {name:'Anaphase',detail:'Sister chromatids separate and become daughter chromosomes. Each pole receives the same chromosome complement.'},\n {name:'Telophase and cytokinesis',detail:'Nuclei reform and cytoplasm divides. Two daughter cells each have 2n = 4 in this model, usually genetically alike except for new mutations.'}],\n questions:[q('What separates during mitotic anaphase?',['Homologous pairs only','Sister chromatids','Whole nuclei'],1,'Sister chromatids separate and each becomes a chromosome.'),q('After S phase, our 2n = 4 cell contains…',['4 chromosomes, 8 chromatids','8 chromosomes, 8 chromatids','2 chromosomes'],0,'Replication doubles DNA content, not the number of centromeres.'),q('What is the usual result here?',['Four haploid cells','Two diploid cells','One gamete'],1,'One division maintains the starting ploidy.')],investigation:['Pause at S/G2 and count chromosomes separately from chromatids.','Compare metaphase with anaphase. Track one colour to both poles.','Draw the two daughter cells and justify their chromosome number.'],teacher:'Assign pupils the roles of chromosomes and spindle fibres using cards. Ask the class to predict the next stage before advancing. Keep chromosome counts separate from DNA quantity.',misconception:'DNA copying is in interphase, not prophase. Mitosis can also occur in haploid cells; this example starts diploid.',source:'10-2-the-cell-cycle',limit:'A schematic 2n = 4 animal-cell example; stages have equal playback durations, not real biological durations.'},\n meiosis:{title:'Meiosis and genetic variation',intro:'Follow one DNA replication and two divisions. Compare homologous chromosome separation with sister chromatid separation.',principle:'Meiosis I reduces chromosome sets; meiosis II separates sister chromatids without another S phase.',steps:[\n {name:'Before S phase · 2n = 4',detail:'Two homologous pairs are shown: one long and one short. Blue and coral indicate the two parental origins, not sex chromosomes.'},\n {name:'DNA replication',detail:'Each of 4 chromosomes is copied into two sister chromatids. DNA replicates once before meiosis I.'},\n {name:'Prophase I · crossing over',detail:'Homologues pair. Non-sister chromatids exchange corresponding DNA segments; the marked tips show one illustrative crossover.'},\n {name:'Metaphase I',detail:'Homologous pairs align together. Their orientation is independent; use the orientation control to compare two possible arrangements.'},\n {name:'Anaphase I',detail:'Homologues separate, while sister chromatids remain joined. Each pole receives one member of each homologous pair.'},\n {name:'After meiosis I',detail:'Two haploid cells each contain n = 2 replicated chromosomes. Haploid does not mean that every chromosome has a single chromatid.'},\n {name:'Metaphase II',detail:'With no intervening DNA replication, replicated chromosomes align individually in each haploid cell.'},\n {name:'Anaphase II',detail:'Sister chromatids separate in both cells. The exchanged DNA segments can make sisters genetically different.'},\n {name:'Four haploid products',detail:'Each product has n = 2 single-chromatid chromosomes. Animal gametogenesis may produce unequal cytoplasm, as in oogenesis; four equal circles are a schematic.'}],\n questions:[q('What separates in meiosis I?',['Sister chromatids','Homologous chromosomes','Ribosomes'],1,'The reduction division separates homologues; sisters remain attached.'),q('Is there an S phase between meiosis I and II?',['Yes','No'],1,'One replication precedes the two divisions.'),q('Where does crossing over occur?',['Non-sister chromatids of homologues','Between unrelated cells','Only after fertilisation'],0,'Corresponding segments exchange between paired homologous chromosomes.')],investigation:['Compare 2n = 4 before S phase with n = 2 after division I.','Change orientation at metaphase I and track the short pair.','Toggle crossing over and compare the marked segments in all four products.'],teacher:'Give each pair two colours of long and short chromosome cards. Have students predict division-I products, then contrast the two types of separation with mitosis.',misconception:'Haploid chromosomes can still be replicated. Independent assortment and crossing over are distinct. Plant meiosis produces spores; gametes are not the universal direct product.',source:'11-1-the-process-of-meiosis',limit:'Two homologous pairs, one illustrative crossover and two selected orientations; not all genetic outcomes or actual cell geometry.'},\n transpiration:{title:'Transpiration in plants',intro:'Adjust humidity, air movement, temperature and stomatal opening. Compare a simplified relative water-loss index.',principle:'Evaporation and diffusion at leaves contribute to tension that draws water up xylem.',steps:[{name:'Root uptake',detail:'Water enters roots along a water-potential gradient. Roots do not act as a mechanical pump for the whole transpiration stream.'},{name:'Xylem transport',detail:'Cohesion and adhesion help maintain a continuous water column under tension. This model assumes an adequate water supply.'},{name:'Leaf evaporation',detail:'Water evaporates from moist mesophyll surfaces into leaf air spaces.'},{name:'Stomatal diffusion',detail:'Water vapour diffuses through stomata toward drier air. Guard cells regulate the aperture.'}],questions:[q('With everything else fixed, higher humidity usually…',['Lowers transpiration','Raises it indefinitely','Stops photosynthesis instantly'],0,'A smaller vapour gradient reduces diffusion.'),q('Which tissue carries this water stream?',['Phloem','Xylem','Epidermis only'],1,'Xylem transports water and dissolved mineral ions.'),q('Does this index predict field water loss in mL/hour?',['Yes','No'],1,'It is an illustrative relative index; leaf area and plant physiology are omitted.')],investigation:['Record the index at 20%, 50% and 80% humidity, keeping other controls fixed.','Repeat for air movement. Explain why it has diminishing influence here.','Close stomata and describe the trade-off between conserving water and taking in carbon dioxide.'],teacher:'Ask groups to predict an environmental effect before changing one variable. Keep a results table and compare fair tests. Discuss why drought-induced stomatal closure can reverse a simple temperature trend.',misconception:'Transpiration is water-vapour loss, not the upward water stream itself. A potometer estimates water uptake, which is not identical to water lost.',source:'30-5-transport-of-water-and-solutes-in-plants',limit:'Illustrative relative index, no physical rate units. Fixed water supply, no wilting, leaf-area variation, cuticular loss or automatic stomatal feedback.'},\n classification:{title:'Classification and scientific names',intro:'Explore Domain and the KPCOFGS hierarchy. Compare human and domestic cat examples and practise binomial naming.',principle:'Nested taxa organise organisms; a scientific species name combines genus with specific epithet.',steps:[{name:'Domain',detail:'A rank above kingdom. These two examples are Eukarya. The three-domain framework also recognises Bacteria and Archaea.'},{name:'Kingdom',detail:'Both examples are Animalia. Kingdom systems differ among curricula and change as evidence develops.'},{name:'Phylum',detail:'Both belong to Chordata, a group including animals with a notochord at some stage of development.'},{name:'Class',detail:'Both are Mammalia: mammals, which share features including mammary glands and hair.'},{name:'Order',detail:'Humans are Primates; domestic cats are Carnivora. Broad shared groups do not imply the same species.'},{name:'Family',detail:'Humans are Hominidae; domestic cats are Felidae.'},{name:'Genus',detail:'Homo for humans and Felis for domestic cats. Capitalise the genus in a binomial name.'},{name:'Species',detail:'Homo sapiens and Felis catus. Write both words in italics (or underline separately in handwriting). The specific epithet alone is not the full species name.'}],questions:[q('Which rank is immediately above genus?',['Species','Family','Class'],1,'The sequence is order, family, genus, species.'),q('Which is correctly written?',['homo Sapiens','Homo sapiens','Sapiens'],1,'The genus starts with a capital and the epithet is lower case; italicise both.'),q('Do human and cat belong to the same order?',['Yes','No'],1,'Human: Primates. Cat: Carnivora.')],investigation:['Advance from Domain to Species and identify where the two examples first differ.','Write KPCOFGS in order, then add Domain above it.','Explain why a shared class does not establish identical species.'],teacher:'Let teams arrange rank cards from broad to narrow, then defend the placement of each example. Ask a partner to check capitalisation and italics in a scientific name.',misconception:'Taxonomic rank is not a ladder of progress. A species concept based only on interbreeding does not work equally well for all organisms.',source:'20-1-organizing-life-on-earth',limit:'Two familiar examples in a simplified ranked hierarchy; not a complete phylogenetic tree or universal kingdom system.'},\n 'life-processes':{title:'Characteristics of living things',intro:'Explore life processes and evaluate evidence. Mnemonics vary; use the named processes and the combined evidence rather than one sign alone.',principle:'Life is identified using interacting properties across cells, organisms and populations, not motion alone.',steps:[{name:'Movement',detail:'Animals may move from place to place; plants also show growth movements and internal transport. Motion alone does not establish life.'},{name:'Respiration',detail:'Cells release usable energy from chemical substrates. Cellular respiration is distinct from breathing and can be aerobic or anaerobic.'},{name:'Nutrition',detail:'Organisms obtain materials and energy. Photosynthesis is a mode of autotrophic nutrition; animals obtain organic nutrients by feeding.'},{name:'Sensitivity / irritability',detail:'Organisms detect and respond to stimuli, such as light, touch or chemical signals.'},{name:'Growth and development',detail:'Living systems grow through cellular processes and develop organised structures; simple external accumulation is not sufficient evidence of life.'},{name:'Excretion',detail:'Removal of metabolic wastes such as carbon dioxide or nitrogenous compounds. Egestion of undigested food is different.'},{name:'Reproduction',detail:'New organisms arise from living systems. A sterile individual can still be alive; reproduction describes continuation of lineages.'},{name:'Death',detail:'Individual life ends through irreversible loss of integrated function. Death alone is not a diagnostic test for life.'},{name:'Competition',detail:'Organisms may compete for limited resources. Competition also occurs in other systems, so it is not sufficient evidence on its own.'},{name:'Adaptation',detail:'Heritable traits can become more common across generations through natural selection. This differs from short-term acclimatisation of an individual.'}],questions:[q('A car moves and uses fuel. Is that alone evidence it is alive?',['Yes','No'],1,'Life requires a coordinated set of properties including cellular organisation.'),q('Excretion is…',['Removal of metabolic waste','Removal of undigested food','Only movement'],0,'Egestion concerns undigested food; excretion concerns metabolic wastes.'),q('A sterile animal is…',['Not alive','Still alive'],1,'An individual need not reproduce to be alive.')],investigation:['For each process, propose a plant example and an animal example.','Compare a seed, a flame and a moving vehicle using several lines of evidence.','Explain respiration versus breathing and adaptation versus acclimatisation.'],teacher:'Ask groups to sort evidence cards into strong, weak and insufficient evidence for life. Include a dormant seed so lack of visible movement is not treated as proof of non-life.',misconception:'MRNIGERDCA is a memory aid, not a universal definition. Homeostasis, cellular organisation and evolution also matter; the processes should be considered together.',source:'1-2-themes-and-concepts-of-biology',limit:'A conceptual explorer, not a biological test or a claim that every process must be visibly present in every individual.'}\n};\nexport function transpirationIndex(humidity:number,wind:number,temperature:number,opening:number){\n const clamp=(x:number,lo:number,hi:number)=>Math.min(hi,Math.max(lo,x));\n return 100*(1-clamp(humidity,0,100)/100)*(0.5+0.5*clamp(wind,0,5)/(1+clamp(wind,0,5)))*Math.pow(1.04,clamp(temperature,10,40)-25)*clamp(opening,0,100)/100;\n}\nexport const taxonomy=[['Eukarya','Animalia','Chordata','Mammalia','Primates','Hominidae','Homo','Homo sapiens'],['Eukarya','Animalia','Chordata','Mammalia','Carnivora','Felidae','Felis','Felis catus']];\n", "src/lib/explorer/locales.ts": "import type { Language } from './catalog';\nexport const languageNames = { en: 'English', yo: 'Yorùbá', ha: 'Hausa', ig: 'Igbo' };\nexport const ui = {\n en: { heading:'Explore every topic', intro:'Find an existing simulation, read its explanation and open it with supported settings. No paid AI API is needed.', language:'Response language', topic:'Topic', automatic:'Detect from prompt', prompt:'Describe a topic or enter key=value settings', apply:'Explain and prepare', open: