ẹlẹ̀ nínú simulation.', protected:'Ìṣe Minitab yìí ṣì nílò student login tó wà tẹ́lẹ̀.', detected:'Kókó tí a yàn', error:'A kò lè túmọ̀ ìbéèrè yìí.', noMatch:'Yan kókó kan tàbí sọ orúkọ rẹ̀. Àpẹẹrẹ yìí ń ṣí àwọn ìṣe tí ó ti wà nìkan.', invalid:'A kò lè túmọ̀ díẹ̀ nínú àwọn iye. Lo keys àti ààlà tí a fi hàn nísàlẹ̀.', example:'Àpẹẹrẹ ìbéèrè', attached:'Àwọn iye tí a pèsè', reference:'Àwọn kókó tó jọra', close:'Pa àlàyé mọ́', review:'Yí kókó tàbí àwọn iye padà', numerical:'Àbájáde ìṣirò', supplied:'Àwọn iye tí o béèrè', omitted:'Iye tí o kò sọ yóò jẹ́ iye àkọ́kọ́ tó wà nísàlẹ̀.', bridge:'A lè fi àwọn iye ránṣẹ́ sí controls tí a ṣe àkójọ rẹ̀.', notes:'Àwọn orúkọ sáyẹ́ǹsì àti ọ̀rọ̀ inú ìṣe àtijọ́ ṣì wà ní Gẹ̀ẹ́sì. Kí olùkọ́ tó mọ èdè náà ṣàyẹ̀wò ìtumọ̀ kí a tó lò ó ní kíláàsì.' },\n ha: { heading:'Binciki dukkan batutuwa', intro:'Nemo simulation da yake akwai, karanta bayaninsa, sannan buɗe shi da saitunan da ake goyon baya. Ba a buƙatar API mai kuɗi.', language:'Harshen amsa', topic:'Batun darasi', automatic:'Zaɓa daga tambaya', prompt:'Bayyana batu ko rubuta key=value', apply:'Bayyana kuma shirya', open:'Buɗe simulation', defaults:'Saitunan farko', settings:'Saitunan da za a yi amfani da su', modes:'Yanayin simulation', manual:'Yi amfani da controls na aikin don saitunan da ba a lissafa a nan ba.', free:'Samfurin kyauta mai ƙa’idoji · ba AI mai samar da sabbin amsoshi ba', source:'Bayani kan batu (Turanci)', principle:'Muhimmiyar alaƙa ko ƙa’ida', limitations:'Wannan samfurin koyarwa ne. Duba sharuɗɗansa da units. Mai bayanin ba ya ganin abin da ke faruwa a simulation.', protected:'Wannan aikin Minitab yana riƙe buƙatar student login ɗinsa.', detected:'Batun da aka zaɓa', error:'An kasa fahimtar wannan buƙata.', noMatch:'Zaɓi batu ko rubuta sunansa. Samfurin yana buɗe ayyukan da aka riga aka yi rajista kawai.', invalid:'An kasa fahimtar wasu saituna. Yi amfani da keys da iyakokin da aka nuna a ƙasa.', example:'Misalin tambaya', attached:'Saitunan da aka shirya', reference:'Batutuwa masu alaƙa', close:'Ɓoye bayani', review:'Sauya batu ko saituna', numerical:'Sakamakon lissafi', supplied:'Ƙimomin da aka nema', omitted:'Abin da ba a bayyana ba yana riƙe ma’aunin farko da ke ƙasa.', bridge:'Ana iya aika ƙimomi zuwa controls da aka lissafa.', notes:'Sunayen kimiyya da rubutun ayyukan asali suna da Turanci. Malamin fannin da ya iya harshen ya duba fassarar kafin amfani a aji.' },\n ig: { heading:'Nyochaa isiokwu niile', intro:'Chọta simulation dị adị, gụọ nkọwa ya, ma mepee ya na ntọala akwadoro. Ọ chọghị API a na-akwụ ụgwọ.', language:'Asụsụ azịza', topic:'Isiokwu', automatic:'Chọpụta site n’arịrịọ', prompt:'Kọwaa isiokwu ma ọ bụ dee key=value', apply:'Kọwaa ma kwadebe', open:'Mepee simulation', defaults:'Ntọala mbido', settings:'Ntọala a ga-etinye', modes:'Ụdị simulation', manual:'Jiri controls nke ọrụ ahụ maka ntọala ndị a na-edeghị ebe a.', free:'Ihe ngosi efu na-eji iwu · ọ bụghị AI na-emepụta azịza ọhụrụ', source:'Nkọwa isiokwu (Bekee)', principle:'Mmekọrịta ma ọ bụ iwu bụ isi', limitations:'Nke a bụ ihe nlereanya mmụta. Lelee ọnọdụ na units ya. Onye nkọwa anaghị ahụ simulation na-agba.', protected:'Ọrụ Minitab a ka na-achọ student login ya.', detected:'Isiokwu ahọpụtara', error:'Aghọtaghị arịrịọ a.', noMatch:'Họrọ isiokwu ma ọ bụ dee aha ya. Ihe ngosi a na-emepe naanị ọrụ ndị e debanyere aha.', invalid:'Aghọtaghị ụfọdụ ntọala. Jiri keys na oke ndị e gosiri n’okpuru.', example:'Ihe atụ arịrịọ', attached:'Ntọala akwadoro', reference:'Isiokwu ndị metụtara ya', close:'Zoo nkọwa', review:'Gbanwee isiokwu ma ọ bụ ntọala', numerical:'Nsonaazụ mgbakọ', supplied:'Ụkpụrụ a rịọrọ', omitted:'Ihe a na-akọwaghị ga-eji ntọala mbido dị n’okpuru.', bridge:'Enwere ike iziga ụkpụrụ na controls ndị e depụtara.', notes:'Aha sayensị na ederede ọrụ mbụ ka dị na Bekee. Onye nkuzi maara asụsụ na ihe ọmụmụ ahụ kwesịrị inyocha nsụgharị tupu iji ya n’ụlọ akwụkwọ.' },\n};\n// Overview concepts supplement, rather than claim to translate, the original English activities.\nconst concepts: Record<string,[string,string,string]> = {\n \"bio-cells\":[\"Cell ni ẹyọ ìpìlẹ̀ ohun alààyè. Ṣe àfiwé cell ewéko àti ẹranko; yan organelle kí o ka iṣẹ́ rẹ̀.\", \"Cell shi ne tushen ginin halittu masu rai. Kwatanta cells na tsirrai da dabbobi, sannan zaɓi organelle don koyon aikinsa.\", \"Cell bụ nkeji ntọala ihe ndị dị ndụ. Tụlee cell osisi na nke anụmanụ; họrọ organelle ka ị mụta ọrụ ya.\"],\n \"bio-mitosis\":[\"Ní mitosis, cell ń pín lẹ́yìn tí DNA ti ṣe ẹ̀dà. Iye chromosome set nínú ọmọ cell kọọkan ń dúró bí ti ìbẹ̀rẹ̀.\", \"A mitosis, cell yana rabuwa bayan an kwafi DNA. Yawan sets na chromosomes a kowace sabuwar cell yana daidai da na farko.\", \"Na mitosis, cell na-ekewa mgbe e depụtachara DNA. Ọnụọgụ sets chromosomes na cell ọhụrụ ọ bụla na-anọ otu ọ dị na mbụ.\"],\n \"bio-meiosis\":[\"Meiosis ní ìpín méjì lẹ́yìn ẹ̀dà DNA kan. Homologues ń yà ní ìpín àkọ́kọ́; sister chromatids ń yà ní ìkejì.\", \"Meiosis yana da rabewa biyu bayan kwafin DNA sau ɗaya. Homologues suna rabuwa a farko; sister chromatids a na biyu.\", \"Meiosis nwere nkewa abụọ mgbe e depụtachara DNA otu ugboro. Homologues na-ekewa na mbụ; sister chromatids na nke abụọ.\"],\n \"bio-transpiration\":[\"Transpiration ni pípàdánù omi gẹ́gẹ́ bí oru láti ewéko. Yí humidity àti stomatal opening padà kí o ṣe àfiwé; index yìí kì í ṣe ìwọ̀n gidi.\", \"Transpiration shi ne asarar ruwa a matsayin tururi daga tsirrai. Sauya humidity da buɗewar stomata don kwatanta; index ɗin ba ainihin ma’auni ba ne.\", \"Transpiration bụ mfu mmiri dị ka uzuoku site n’osisi. Gbanwee humidity na oghere stomata ka ị tụlee; index a abụghị ọnụego a tụrụ n’eziokwu.\"],\n \"bio-classification\":[\"Ìsọ̀rí ohun alààyè ń lọ láti Domain sí Species. Orúkọ sáyẹ́ǹsì species ní genus àti specific epithet.\", \"Rarraba halittu yana daga Domain zuwa Species. Sunan kimiyya na species ya haɗa genus da specific epithet.\", \"Nhazi ihe ndị dị ndụ si Domain ruo Species. Aha sayensị species nwere genus na specific epithet.\"],\n \"bio-life-processes\":[\"Lo ọ̀pọ̀ ẹ̀rí láti mọ ohun alààyè. Ìṣípò nìkan kò tó; respiration yàtọ̀ sí mímí.\", \"Yi amfani da hujjoji da dama don gane abu mai rai. Motsi kaɗai bai isa ba; respiration ya bambanta da numfashi.\", \"Jiri ọtụtụ ihe akaebe mara ihe dị ndụ. Mmegharị naanị ezughị; respiration dị iche na iku ume.\"],\n\n skeleton:['Egungun ń gbé ara dúró, ó ń dáàbò bo àwọn ẹ̀yà ara, ó sì ń ran ìṣípò lọ́wọ́. Àgbàlagbà sábà ní egungun 206: 80 axial àti 126 appendicular. Yan egungun kan kí o ka ibi àti iṣẹ́ rẹ̀.','Ƙasusuwan jiki suna tallafa wa jiki, suna kare gaɓobin ciki kuma suna taimaka wa motsi. Yawanci babban mutum yana da ƙasusuwa 206: 80 axial da 126 appendicular. Zaɓi ƙashi don koyon inda yake da aikinsa.','Ọkpụkpụ na-akwado ahụ, na-echebe akụkụ ahụ dị n’ime ma na-enyere mmegharị aka. Okenye na-enwekarị ọkpụkpụ 206: 80 axial na 126 appendicular. Họrọ ọkpụkpụ ka ị mụta ebe ọ dị na ọrụ ya.'],\n force:['Net force ló ń fa acceleration; bí mass bá pọ̀ sí i fún force kan náà, acceleration yóò dín kù.','Ƙarfin net force yana haifar da acceleration; idan mass ya ƙaru a force ɗaya, acceleration yana raguwa.','Net force na-ebute acceleration; ma mass bawanye na force otu, acceleration na-ebelata.'],\n circuit:['Voltage, current àti resistance ní ìbáṣepọ̀. Òfin Ohm kan ohmic conductor ní ipò ara tó dúró ṣinṣin.','Voltage, current da resistance suna da alaƙa. Dokar Ohm tana aiki ga ohmic conductor a yanayin jiki da bai sauya ba.','Voltage, current na resistance nwere mmekọrịta. Iwu Ohm na-arụ ọrụ maka ohmic conductor mgbe ọnọdụ anụ ahụ ya anaghị agbanwe.'],\n wave:['Wave ń gbé agbára. Frequency àti wavelength ló pinnu speed nípasẹ̀ v = fλ.','Wave yana ɗaukar makamashi. Frequency da wavelength suna da alaƙa da speed ta v = fλ.','Wave na-ebufe ike. Frequency na wavelength jikọtara speed site na v = fλ.'],\n projectile:['Ya velocity sí apá petele àti inárọ̀; gravity ń yí apá inárọ̀ padà. Àwòṣe yìí kò ka ìdènà afẹ́fẹ́ sí.','Raba velocity zuwa na kwance da na tsaye; gravity yana sauya na tsaye. Wannan samfurin yana yin watsi da juriyar iska.','Kewaa velocity n’akụkụ kwụ ọtọ n’ala na nke elu; gravity na-agbanwe akụkụ elu. Ihe nlereanya a na-eleghara mgbochi ikuku anya.'],\n oscillation:['Ìṣípò tó ń padà sẹ́yìn àti síwájú ni oscillation. Mass, restoring force àti damping lè yí ìṣípò rẹ̀ padà.','Oscillation motsi ne na kai-komo. Mass, restoring force da damping na iya sauya motsin.','Oscillation bụ mmegharị azụ na ihu. Mass, restoring force na damping nwere ike ịgbanwe mmegharị ya.'],\n quantum:['Ní quantum physics, àwọn iye agbára lè wà ní ìpele pàtó. Àwòṣe àti àwọn ààlà rẹ̀ gbọ́dọ̀ hàn gbangba.','A quantum physics, makamashi na iya kasancewa a matakai na musamman. A bayyana samfurin da iyakokinsa.','Na quantum physics, ike nwere ike ịdị n’ọkwa a kapịrị ọnụ. A ghaghị ịkọwa ihe nlereanya na oke ya.'],\n atom:['Iye proton ló ń dá element mọ̀. Àwòṣe atom ń ràn wá lọ́wọ́ láti ṣàlàyé ẹ̀rí, kì í ṣe fọ́tò atom gidi.','Adadin proton yana gane element. Samfurin atom yana taimaka wajen bayyana shaida, ba hoton atom na gaske ba ne.','Ọnụọgụ proton na-egosi element. Ihe nlereanya atom na-enyere aka ịkọwa ihe akaebe; ọ bụghị foto atom n’eziokwu.'],\n chemistry:['Ìpín atom àti bí wọ́n ṣe so pọ̀ ṣe pàtàkì. Kíkọ formula nìkan kò fi hàn pé compound wà tàbí pé ó dúró ṣinṣin.','Rabon atoms da yadda suka haɗu suna da muhimmanci. Formula kaɗai ba ya tabbatar da wanzuwa ko kwanciyar compound.','Oke atoms na otú ha si jikọta dị mkpa. Formula naanị anaghị egosi na compound dị adị ma ọ bụ kwụsiri ike.'],\n crystal:['Àtòjọ atom àti àwọn ibi tí wọ́n jókòó ṣe pàtàkì nínú crystal. Geometric screening kò tó láti fi stability hàn.','Tsarin atoms da wurarensu suna da muhimmanci a crystal. Geometric screening kaɗai ba ya tabbatar da stability.','Nhazi atoms na ebe ha nọ dị mkpa na crystal. Geometric screening naanị anaghị egosi stability.'],\n decay:['Half-life ni àkókò tí iye tó kù ń dín sí ìdajì ní ìsúnmọ́ ìṣirò. Decay atom kọ̀ọ̀kan jẹ́ ohun tó dá lórí probability.','Half-life shi ne lokacin da adadin da ake sa ran zai rage ya koma rabi. Decay na atom guda yana da probability.','Half-life bụ oge ọnụọgụ a na-atụ anya ka fọdụrụ ga-ebelata ọkara. Decay nke atom ọ bụla dabere na probability.'],\n vector:['Vector ní magnitude àti direction. Ya a sí components kí o tó ṣe ìṣirò tí ó bá yẹ.','Vector yana da magnitude da direction. Raba shi zuwa components idan hakan ya dace da lissafi.','Vector nwere magnitude na direction. Kewaa ya na components mgbe ọ dị mkpa maka mgbakọ.'],\n trig:['Lórí unit circle, cosine ni x-coordinate, sine sì ni y-coordinate. Ṣàyẹ̀wò boya degree tàbí radian ni a ń lò.','A unit circle, cosine shi ne x-coordinate, sine kuma y-coordinate. Duba ko ana amfani da degrees ko radians.','Na unit circle, cosine bụ x-coordinate, sine bụ y-coordinate. Lelee ma a na-eji degrees ma ọ bụ radians.'],\n gas:['Pressure, volume àti temperature ní ìbáṣepọ̀. Lo temperature ní kelvin nínú ideal gas equation.','Pressure, volume da temperature suna da alaƙa. Yi amfani da temperature a kelvin a ideal gas equation.','Pressure, volume na temperature nwere mmekọrịta. Jiri temperature dị na kelvin n’ime ideal gas equation.'],\n heat:['Agbára ń sàn láti ibi tó gbóná sí ibi tó tutù. Material àti geometry ń ní ipa lórí iyára gbigbe ooru.','Makamashi yana gudana daga wuri mai zafi zuwa mai sanyi. Material da geometry suna shafar saurin canja zafi.','Ike na-esi ebe dị ọkụ gaa ebe dị oyi. Material na geometry na-emetụta ọsọ mbufe okpomọkụ.'],\n friction:['Static friction lè yí padà títí dé ààlà rẹ̀. Kinetic friction ń tako relative sliding.','Static friction na iya sauyawa har zuwa iyakarsa. Kinetic friction yana adawa da zamewar abubuwa.','Static friction nwere ike ịgbanwe ruo n’oke ya. Kinetic friction na-egbochi ịmịgharị ihe n’elu ibe ya.'],\n equilibrium:['Fún static equilibrium, net force àti net turning effect gbọ́dọ̀ jẹ́ odo.','A static equilibrium, net force da net turning effect su zama sifili.','Maka static equilibrium, net force na net turning effect ga-abụ efu.'],\n elastic:['Nínú proportional limit, force àti extension ń pọ̀ sí i ní ìpín kan náà. Kọjá ààlà yìí lè yí ìhùwàsí padà.','A cikin proportional limit, force da extension suna ƙaruwa a rabo ɗaya. Bayan wannan iyaka hali na iya sauyawa.','N’ime proportional limit, force na extension na-abawanye n’otu oke. Mgbe e gafere oke ahụ, omume nwere ike ịgbanwe.'],\n induction:['Ìyípadà magnetic flux linkage ló ń fa induced voltage. Direction rẹ̀ ń tako ìyípadà tó fa a.','Sauyin magnetic flux linkage yana haifar da induced voltage. Direction ɗinsa yana adawa da sauyin da ya haifar da shi.','Mgbanwe magnetic flux linkage na-ebute induced voltage. Direction ya na-emegide mgbanwe kpatara ya.'],\n charge:['Charge ń ṣẹ̀dá electric field; àwọn field sì lè darapọ̀. Àmì charge ṣe pàtàkì fún direction force.','Charge yana samar da electric field, kuma fields na iya haɗuwa. Alamar charge tana da muhimmanci ga direction na force.','Charge na-emepụta electric field, fields nwekwara ike ijikọta. Akara charge dị mkpa maka direction force.'],\n capacitor:['Capacitance so charge pọ̀ mọ́ potential difference. Geometry àti ohun tó wà láàárín plates ń ní ipa.','Capacitance yana haɗa charge da potential difference. Geometry da abin da ke tsakanin plates suna da tasiri.','Capacitance jikọtara charge na potential difference. Geometry na ihe dị n’etiti plates na-emetụta ya.'],\n magnetic:['Electric current lè ṣẹ̀dá magnetic field. Force lórí conductor sinmi lórí field, current àti direction.','Electric current na iya samar da magnetic field. Force a conductor ya dogara da field, current da direction.','Electric current nwere ike ịmepụta magnetic field. Force n’elu conductor dabere na field, current na direction.'],\n reflection:['Ní reflection, igun tí ray fi wọlé dọ́gba pẹ̀lú igun tí ó fi padà, a sì ń wọn wọn láti normal.','A reflection, kusurwar shigowa tana daidai da ta dawowa; ana auna su daga normal.','Na reflection, nkuku mbata hà nkuku nlọghachi; a na-atụ ha site na normal.'],\n refraction:['Ray lè yí direction padà ní ààlà media. Refractive indices àti igun ló pinnu ìbáṣepọ̀ Snell.','Ray na iya sauya direction a iyakar media. Refractive indices da kusurwoyi suna bin dokar Snell.','Ray nwere ike ịgbanwe direction n’ókè media. Refractive indices na nkuku na-agbaso iwu Snell.'],\n optics:['Ray model ń lo ìlà tó tọ́ nínú uniform medium láti ṣàlàyé òjìji àti image.','Ray model yana amfani da madaidaiciyar hanya a uniform medium don bayyana inuwa da image.','Ray model na-eji ụzọ kwụ ọtọ n’ime uniform medium ịkọwa onyinyo na image.'],\n polarization:['Polarizer ń yan direction electric-field vibration. Bí igun àwọn polarizer ṣe yàtọ̀ ń yí intensity padà.','Polarizer yana zaɓar direction na electric-field vibration. Bambancin kusurwa yana sauya intensity.','Polarizer na-ahọrọ direction electric-field vibration. Ọdịiche nkuku na-agbanwe intensity.'],\n semiconductor:['Àwọn carrier àti bias ń ní ipa lórí conduction nínú semiconductor.','Carriers da bias suna shafar conduction a semiconductor.','Carriers na bias na-emetụta conduction na semiconductor.'],\n transistor:['Bias tó wà ní terminal ń darí conduction. Ṣàyẹ̀wò mode àti àwọn àfojúsùn device model.','Bias a terminals yana sarrafa conduction. Duba mode da sharuɗɗan device model.','Bias na terminals na-achịkwa conduction. Lelee mode na ọnọdụ device model.'],\n band:['Energy bands àti carrier population ń ràn wá lọ́wọ́ láti ṣàlàyé electrical conduction.','Energy bands da yawan carriers suna taimakawa wajen bayyana electrical conduction.','Energy bands na ọnụọgụ carriers na-enyere aka ịkọwa electrical conduction.'],\n earth:['Àwọn layer Earth àti atmosphere ní properties tó yàtọ̀. Àwòṣe yìí jẹ́ ohun ìrànwọ́ ẹ̀kọ́.','Layers na Earth da atmosphere suna da properties daban-daban. Wannan samfurin kayan koyarwa ne.','Layers nke Earth na atmosphere nwere properties dị iche iche. Ihe nlereanya a bụ enyemaka mmụta.'],\n geophysics:['Àwọn signal physics lè fún wa ní ẹ̀rí nípa abẹ́ ilẹ̀. Ọ̀pọ̀ model lè ṣàlàyé data kan náà.','Signals na physics na iya ba da shaida kan ƙarƙashin ƙasa. Models da yawa na iya bayyana data ɗaya.','Signals physics nwere ike inye ihe akaebe gbasara ihe dị n’okpuru ala. Models dị iche iche nwere ike ịkọwa otu data.'],\n solar:['Gravity ń darí orbit. Fún àwọn ohun tó ń yí central mass kan náà ká, T² ní ìbáṣepọ̀ pẹ̀lú a³.','Gravity yana sarrafa orbit. Ga abubuwan da ke zagaya central mass ɗaya, T² yana da alaƙa da a³.','Gravity na-achịkwa orbit. Maka ihe ndị na-agba otu central mass gburugburu, T² jikọtara a³.'],\n tectonics:['Plate motion ń so àwọn àpẹẹrẹ lórí ilẹ̀ pọ̀ mọ́ geological processes.','Plate motion yana haɗa tsarin saman ƙasa da geological processes.','Plate motion jikọtara usoro elu ala na geological processes.'],\n calculus:['Derivatives ń ṣàlàyé ìyípadà agbègbè kékeré; integrals ń kó àwọn ipa kékeré jọ.','Derivatives suna bayyana sauyi na gida; integrals suna tara ƙananan tasiri.','Derivatives na-akọwa mgbanwe mpaghara nta; integrals na-achịkọta obere mmetụta.'],\n matrix:['Eigenvector ń pa direction rẹ̀ mọ́ lábẹ́ linear transformation, àfi scaling.','Eigenvector yana riƙe direction ɗinsa ƙarƙashin linear transformation sai dai scaling.','Eigenvector na-edobe direction ya n’okpuru linear transformation, ma scaling nwere ike ịgbanwe.'],\n fourier:['A lè tú signal sí àwọn frequency components láti lóye ìṣètò rẹ̀.','Ana iya raba signal zuwa frequency components don fahimtar tsarinsa.','Enwere ike ikewa signal na frequency components iji ghọta nhazi ya.'],\n special:['Special functions ń farahàn nínú equations physics àti mathematics. Àwọn ààlà problem ló ń yan solution tó yẹ.','Special functions suna bayyana a equations na physics da mathematics. Boundary conditions suna zaɓar solution da ya dace.','Special functions na-apụta n’equations physics na mathematics. Boundary conditions na-ahọrọ solution kwesịrị ekwesị.'],\n};\nexport function conceptExplanation(concept:string, language:Language, english:str