      \"default\": \"front\",\n        \"options\": [\n          \"front\",\n          \"back\"\n        ]\n      },\n      {\n        \"key\": \"division\",\n        \"default\": \"all\",\n        \"options\": [\n          \"all\",\n          \"axial\",\n          \"appendicular\"\n        ]\n      },\n      {\n        \"key\": \"labels\",\n        \"default\": \"on\",\n        \"options\": [\n          \"on\",\n          \"off\"\n        ]\n      },\n      {\n        \"key\": \"activity\",\n        \"default\": \"explore\",\n        \"options\": [\n          \"explore\",\n          \"identify\",\n          \"classify\"\n        ]\n      }\n    ],\n    \"protected\": false\n  },\n  {\n    \"id\": \"biology-cells\",\n    \"route\": \"/biology/cells\",\n    \"subject\": \"Biology\",\n    \"title\": \"Cells and organelles\",\n    \"description\": \"Compare plant and animal cell structures and explain selected organelle functions.\",\n    \"principle\": \"Compare plant and animal cell structures and explain selected organelle functions.\",\n    \"concept\": \"bio-cells\",\n    \"aliases\": [\n      \"cells\",\n      \"cell organelles\",\n      \"plant cell\",\n      \"animal cell\",\n      \"cellular biology\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"step\",\n        \"label\": \"Stage or structure\",\n        \"unit\": \"index\",\n        \"min\": 0,\n        \"max\": 7,\n        \"default\": 0,\n        \"integer\": true\n      }\n    ],\n    \"modes\": [\n      {\n        \"key\": \"cell\",\n        \"default\": \"plant\",\n        \"options\": [\n          \"plant\",\n          \"animal\"\n        ]\n      },\n      {\n        \"key\": \"labels\",\n        \"default\": \"on\",\n        \"options\": [\n          \"on\",\n          \"off\"\n        ]\n      }\n    ],\n    \"protected\": false\n  },\n  {\n    \"id\": \"biology-mitosis\",\n    \"route\": \"/biology/mitosis\",\n    \"subject\": \"Biology\",\n    \"title\": \"Mitosis and the cell cycle\",\n    \"description\": \"Track one replication and one division, preserving chromosome set number.\",\n    \"principle\": \"Track one replication and one division, preserving chromosome set number.\",\n    \"concept\": \"bio-mitosis\",\n    \"aliases\": [\n      \"mitosis\",\n      \"cell cycle\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"step\",\n        \"label\": \"Stage or structure\",\n        \"unit\": \"index\",\n        \"min\": 0,\n        \"max\": 5,\n        \"default\": 0,\n        \"integer\": true\n      }\n    ],\n    \"modes\": [],\n    \"protected\": false\n  },\n  {\n    \"id\": \"biology-meiosis\",\n    \"route\": \"/biology/meiosis\",\n    \"subject\": \"Biology\",\n    \"title\": \"Meiosis and genetic variation\",\n    \"description\": \"Track homologues then sister chromatids through two divisions and explore genetic variation.\",\n    \"principle\": \"Track homologues then sister chromatids through two divisions and explore genetic variation.\",\n    \"concept\": \"bio-meiosis\",\n    \"aliases\": [\n      \"meiosis\",\n      \"meiotic division\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"step\",\n        \"label\": \"Stage or structure\",\n        \"unit\": \"index\",\n        \"min\": 0,\n        \"max\": 8,\n        \"default\": 0,\n        \"integer\": true\n      }\n    ],\n    \"modes\": [\n      {\n        \"key\": \"crossing\",\n        \"default\": \"on\",\n        \"options\": [\n          \"on\",\n          \"off\"\n        ]\n      },\n      {\n        \"key\": \"orientation\",\n        \"default\": \"original\",\n        \"options\": [\n          \"original\",\n          \"alternate\"\n        ]\n      }\n    ],\n    \"protected\": false\n  },\n  {\n    \"id\": \"biology-transpiration\",\n    \"route\": \"/biology/transpiration\",\n    \"subject\": \"Biology\",\n    \"title\": \"Transpiration in plants\",\n    \"description\": \"Explore humidity, air movement, temperature and stomatal opening with an illustrative relative water-loss index.\",\n    \"principle\": \"Explore humidity, air movement, temperature and stomatal opening with an illustrative relative water-loss index.\",\n    \"concept\": \"bio-transpiration\",\n    \"aliases\": [\n      \"transpiration\",\n      \"plant water loss\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"step\",\n        \"label\": \"Stage or structure\",\n        \"unit\": \"index\",\n        \"min\": 0,\n        \"max\": 3,\n        \"default\": 0,\n        \"integer\": true\n      },\n      {\n        \"key\": \"humidity\",\n        \"label\": \"Humidity\",\n        \"unit\": \"%\",\n        \"min\": 0,\n        \"max\": 100,\n        \"default\": 50\n      },\n      {\n        \"key\": \"wind\",\n        \"label\": \"Air movement\",\n        \"unit\": \"relative\",\n        \"min\": 0,\n        \"max\": 5,\n        \"default\": 1\n      },\n      {\n        \"key\": \"temperature\",\n        \"label\": \"Temperature\",\n        \"unit\": \"°C\",\n        \"min\": 10,\n        \"max\": 40,\n        \"default\": 25\n      },\n      {\n        \"key\": \"opening\",\n        \"label\": \"Stomatal opening\",\n        \"unit\": \"%\",\n        \"min\": 0,\n        \"max\": 100,\n        \"default\": 100\n      }\n    ],\n    \"modes\": [],\n    \"protected\": false\n  },\n  {\n    \"id\": \"biology-classification\",\n    \"route\": \"/biology/classification\",\n    \"subject\": \"Biology\",\n    \"title\": \"Classification and scientific names\",\n    \"description\": \"Compare human and domestic cat ranks from Domain to Species and practise scientific names.\",\n    \"principle\": \"Compare human and domestic cat ranks from Domain to Species and practise scientific names.\",\n    \"concept\": \"bio-classification\",\n    \"aliases\": [\n      \"classification\",\n      \"taxonomy\",\n      \"KPCOFGS\",\n      \"nomenclature\",\n      \"binomial naming\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": 