function safe(file){let current=root;for(const part of file.split('/')){current=path.join(current,part);try{if(fs.lstatSync(current).isSymbolicLink())stop('Symbolic link at '+file);}catch(e){if(e.code!=='ENOENT')throw e;}}}
for(const file of [...Object.keys(files),'.stem-tutor-backups'])safe(file);
const changed=[],conflicts=[];
for(const [file,content] of Object.entries(files)){
 const current=fs.existsSync(file)?fs.readFileSync(file,'utf8'):null;
 if(current!==null&&normalize(current)===normalize(content))continue;
 if((current===null&&expected[file]!==null)||(current!==null&&(expected[file]===null||hash(current)!==expected[file])))conflicts.push(file);
